package com.bank.lake;

import java.io.IOException;
import java.nio.file.Files;
import java.nio.file.Path;
import java.util.Set;
import java.util.TreeSet;
import java.util.logging.Logger;

// Represents a partitioned external table at National Bank of India.
// It owns the base storage path and an IN-MEMORY catalog (stand-in for the Hive metastore).
class PartitionedTradeLake {
    private static final Logger log = Logger.getLogger(PartitionedTradeLake.class.getName());

    private final Path basePath;
    private final String partitionColumn;
    // The catalog: the set of partition values the metastore KNOWS about.
    private final Set<String> registeredPartitions = new TreeSet<>();

    PartitionedTradeLake(Path basePath, String partitionColumn) throws IOException {
        this.basePath = basePath;
        this.partitionColumn = partitionColumn;
        Files.createDirectories(basePath);
        log.info(() -> "Trade lake ready at " + basePath + " partitioned by " + partitionColumn);
    }

    Path getBasePath() { return basePath; }
    String getPartitionColumn() { return partitionColumn; }

    // Register a partition in the catalog (what INSERT INTO ... PARTITION does automatically).
    void registerPartition(String partitionValue) {
        registeredPartitions.add(partitionValue);
        log.info(() -> "Catalog: registered partition " + partitionColumn + "=" + partitionValue);
    }

    void unregisterPartition(String partitionValue) {
        registeredPartitions.remove(partitionValue);
        log.warning(() -> "Catalog: dropped stale partition " + partitionColumn + "=" + partitionValue);
    }

    boolean isRegistered(String partitionValue) {
        return registeredPartitions.contains(partitionValue);
    }

    Set<String> getRegisteredPartitions() {
        return new TreeSet<>(registeredPartitions);
    }
}
