package com.bank.lake;

import java.io.IOException;
import java.nio.file.Files;
import java.nio.file.Path;
import java.util.logging.Logger;

// Simulates an OUTSIDE job (operations settlement batch) that writes trade files
// directly into partition folders WITHOUT telling the catalog.
class ExternalWriter {
    private static final Logger log = Logger.getLogger(ExternalWriter.class.getName());

    private final PartitionedTradeLake lake;

    ExternalWriter(PartitionedTradeLake lake) { this.lake = lake; }

    // Writes a data file into trade_date=<value>/ folder, bypassing the catalog on purpose.
    void writeExternally(String partitionValue, String fileContent) throws IOException {
        Path partitionDir = lake.getBasePath()
                .resolve(lake.getPartitionColumn() + "=" + partitionValue);
        Files.createDirectories(partitionDir);
        Path dataFile = partitionDir.resolve("part-0000.csv");
        Files.writeString(dataFile, fileContent);
        log.warning(() -> "External job wrote folder " + partitionDir
                + " WITHOUT updating the catalog (metastore now out of sync)");
    }
}
