package com.bank.lake;

import java.io.IOException;
import java.nio.file.Files;
import java.nio.file.Path;
import java.util.Set;
import java.util.TreeSet;
import java.util.logging.Logger;
import java.util.stream.Stream;

// This is the heart of the demo: the MSCK REPAIR TABLE logic.
class MetastoreRepairService {
    private static final Logger log = Logger.getLogger(MetastoreRepairService.class.getName());

    private final PartitionedTradeLake lake;

    MetastoreRepairService(PartitionedTradeLake lake) { this.lake = lake; }

    // MSCK REPAIR TABLE: discover folders on disk, add missing partitions to the catalog.
    // When syncPartitions=true it also drops partitions whose folders were deleted (SYNC PARTITIONS).
    void repair(boolean syncPartitions) throws IOException {
        log.info(() -> "MSCK REPAIR TABLE trades" + (syncPartitions ? " SYNC PARTITIONS" : "") + " started");

        Set<String> onDisk = listPartitionsOnDisk();
        Set<String> inCatalog = lake.getRegisteredPartitions();

        // ADD: folders present on disk but missing from the catalog.
        for (String value : onDisk) {
            if (!inCatalog.contains(value)) {
                lake.registerPartition(value);
                log.info(() -> "REPAIR added missing partition: " + value);
            }
        }

        // DROP (sync only): partitions in catalog whose folder no longer exists.
        if (syncPartitions) {
            for (String value : inCatalog) {
                if (!onDisk.contains(value)) {
                    lake.unregisterPartition(value);
                    log.warning(() -> "REPAIR dropped stale partition: " + value);
                }
            }
        }
        log.info(() -> "MSCK REPAIR complete. Catalog now has " + lake.getRegisteredPartitions());
    }

    // Lists partition values by scanning the base directory for trade_date=<value> folders.
    private Set<String> listPartitionsOnDisk() throws IOException {
        String prefix = lake.getPartitionColumn() + "=";
        Set<String> values = new TreeSet<>();
        try (Stream<Path> entries = Files.list(lake.getBasePath())) {
            entries.filter(Files::isDirectory)
                   .map(p -> p.getFileName().toString())
                   .filter(name -> name.startsWith(prefix))
                   .forEach(name -> values.add(name.substring(prefix.length())));
        }
        log.fine(() -> "Folders discovered on disk: " + values);
        return values;
    }
}
