package com.bank.lake;

import java.io.IOException;
import java.nio.file.Files;
import java.nio.file.Path;
import java.util.logging.Logger;

// Simulates the query planner: it can ONLY read partitions the catalog knows about.
class TradeQueryService {
    private static final Logger log = Logger.getLogger(TradeQueryService.class.getName());

    private final PartitionedTradeLake lake;

    TradeQueryService(PartitionedTradeLake lake) { this.lake = lake; }

    // Returns the row count for a date, but only if the partition is registered (partition pruning).
    long countTradesForDate(String partitionValue) throws IOException {
        if (!lake.isRegistered(partitionValue)) {
            log.warning(() -> "Query for " + partitionValue
                    + " returns 0 rows: partition NOT in catalog (even if data exists on disk)");
            return 0L;
        }
        Path dataFile = lake.getBasePath()
                .resolve(lake.getPartitionColumn() + "=" + partitionValue)
                .resolve("part-0000.csv");
        if (!Files.exists(dataFile)) return 0L;
        long rows = Files.readAllLines(dataFile).size();
        log.info(() -> "Query for " + partitionValue + " returned " + rows + " rows from catalog-registered partition");
        return rows;
    }
}
