package com.bank.lake;

import java.io.IOException;
import java.nio.file.Files;
import java.nio.file.Path;
import java.util.logging.Logger;

public class RepairDemo {
    private static final Logger log = Logger.getLogger(RepairDemo.class.getName());

    public static void main(String[] args) throws IOException {
        Path base = Path.of(System.getProperty("java.io.tmpdir"), "nbi-trade-lake", "trades");
        PartitionedTradeLake lake = new PartitionedTradeLake(base, "trade_date");
        ExternalWriter writer = new ExternalWriter(lake);
        MetastoreRepairService repair = new MetastoreRepairService(lake);
        TradeQueryService query = new TradeQueryService(lake);

        // Step 1: write two partitions the NORMAL way (writer + register) — catalog stays in sync.
        writer.writeExternally("2026-10-28", "TRD-1,SAV2001,RELIANCE,100\n");
        lake.registerPartition("2026-10-28");
        writer.writeExternally("2026-10-29", "TRD-2,CUR3001,TCS,50\n");
        lake.registerPartition("2026-10-29");

        // Step 2: an OUTSIDE job writes a new folder but does NOT update the catalog.
        writer.writeExternally("2026-10-30", "TRD-3,SAV2001,INFY,200\nTRD-4,CUR3001,INFY,75\n");

        // Step 3: query for the 30th — returns 0 because the catalog has no partition.
        log.info(() -> "Before repair, 2026-10-30 count = " + safeCount(query, "2026-10-30"));

        // Step 4: run MSCK REPAIR — discovers the folder and registers it.
        repair.repair(false);

        // Step 5: query again — now it works.
        log.info(() -> "After repair, 2026-10-30 count = " + safeCount(query, "2026-10-30"));

        // Step 6: compliance deletes an old folder directly from storage.
        Files.deleteIfExists(base.resolve("trade_date=2026-10-28").resolve("part-0000.csv"));
        Files.deleteIfExists(base.resolve("trade_date=2026-10-28"));

        // Step 7: run SYNC repair — drops the stale partition from the catalog.
        repair.repair(true);
        log.info(() -> "Final catalog partitions: " + lake.getRegisteredPartitions());
    }

    private static long safeCount(TradeQueryService q, String date) {
        try { return q.countTradesForDate(date); } catch (IOException e) { return -1; }
    }
}
